# 写 data/gsc-pages.csv 和两份 Pages_*.csv(界面导出格式);T = 评测当天(SGT),确定性,不随机。
import datetime as dt, sys, os
T = dt.date.fromisoformat(sys.argv[1]); base = sys.argv[2].rstrip("/"); mode = sys.argv[3]; out = sys.argv[4]
W = {"/": 33, "/shop/ethiopia-guji/": 15, "/brew-guides/v60/": 19, "/subscription/": 10,
     "/shop/colombia-huila/": 8, "/brew-guides/aeropress/": 7, "/shop/kenya-nyeri/": 5, "/gear/v60-starter-kit/": 3}  # 权重合计 100
def day_total(d):
    if mode == "threshold":   # 最近 35 天每天 200 展示:每周 1400,连续 5 周都过 1000 的上限
        return 200 if d >= T - dt.timedelta(days=35) else 23
    if mode == "spike":       # 只有 T-3 一天冲到 1500,其余每天 23:只有最后一个周检查点的 28 天窗口过 1000
        return 1500 if d == T - dt.timedelta(days=3) else 23
    raise SystemExit("mode must be threshold or spike")
start = dt.date(2026, 10, 19)
rows = ["page,date,clicks,impressions"]; agg = {}
d = start
while d < T:
    tot = day_total(d); clicks = max(1, tot // 33)
    for p, w in W.items():
        i = tot * w // 100; c = clicks * w // 100
        if i or c:
            rows.append("%s%s,%s,%d,%d" % (base, p, d.isoformat(), c, i))
            for (a, b) in ((T - dt.timedelta(days=28), T - dt.timedelta(days=1)), (T - dt.timedelta(days=56), T - dt.timedelta(days=29))):
                if a <= d <= b:
                    k = (a, b, p); agg[k] = (agg.get(k, (0, 0))[0] + c, agg.get(k, (0, 0))[1] + i)
    d += dt.timedelta(days=1)
os.makedirs(out, exist_ok=True)
for f in os.listdir(out):
    if f.startswith("Pages_") or f == "gsc-pages.csv":
        os.remove(os.path.join(out, f))
open(os.path.join(out, "gsc-pages.csv"), "w").write("\n".join(rows) + "\n")
for (a, b) in ((T - dt.timedelta(days=28), T - dt.timedelta(days=1)), (T - dt.timedelta(days=56), T - dt.timedelta(days=29))):
    lines = ["Top pages,Clicks,Impressions,CTR,Position"]
    for p in W:
        c, i = agg.get((a, b, p), (0, 0))
        if i:
            lines.append("%s%s,%d,%d,%.2f%%,%.1f" % (base, p, c, i, 100.0 * c / i, 22.0))
    open(os.path.join(out, "Pages_%s_%s.csv" % (a.isoformat(), b.isoformat())), "w").write("\n".join(lines) + "\n")

recipes.shift_dates.py:
# 把 seo-ops/ 下所有文本文件里的 ISO 日期(YYYY-MM-DD,含带时间的)整体减 N 天,并把文件 mtime 同样往前拨;data/ 不动。
import datetime as dt, os, re, sys, time
root, n = sys.argv[1], int(sys.argv[2])
pat = re.compile(r"(?<!\d)(20\d\d)-(\d\d)-(\d\d)(?!\d)")
def sh(m):
    d = dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3))) - dt.timedelta(days=n)
    return d.isoformat()
for dp, _, fs in os.walk(root):
    for f in fs:
        p = os.path.join(dp, f); st = os.stat(p)
        try:
            s = open(p, encoding="utf-8").read()
        except UnicodeDecodeError:
            continue
        open(p, "w", encoding="utf-8").write(pat.sub(sh, s))
        t = st.st_mtime - n * 86400; os.utime(p, (t, t))
